'use strict';
const main = document.querySelector('#main');
const state = { mode: 'task', category: '全部', query: '', step: 0, role: 'creator', phase: 0, checks: [false,false,false] };
const cases = [
  {id:'sales',title:'把销售数据变成一份周报',category:'办公分析',output:'CSV → Markdown',level:'入门',status:'规划 · 含设计样本',desc:'从字段确认到分组汇总，每个关键数字都能回到原始数据。',asset:'输入数据 · 计算依据 · 参考周报'},
  {id:'article',title:'从三份资料写成一篇文章',category:'内容创作',output:'资料 → 带来源文章',level:'入门',status:'规划',desc:'把事实、推断和待确认问题分开，练习写作和事实核对。',asset:'资料包 · 事实表 · 初稿与终稿'},
  {id:'slides',title:'把文章做成 8 页演示稿',category:'内容创作',output:'文章 → PPTX',level:'进阶',status:'规划',desc:'从一条汇报主线出发，制作可编辑、可演示的幻灯片。',asset:'文章 · 大纲 · PPTX · 逐页预览'},
  {id:'bug',title:'修复 Bug，并证明修对了',category:'软件开发',output:'代码 → 最小修复与测试',level:'入门',status:'现有材料',desc:'用现有购物车练习理解失败测试、最小改动和回归证据。',asset:'starter · solution · 验证说明',url:'https://codexhandbook.com/cases/use-cases/software-development/fix-a-bug-with-verification/'},
  {id:'review',title:'审查一次变更，找到真正的问题',category:'软件开发',output:'diff → 审查报告',level:'进阶',status:'规划升级',desc:'分清未提交变更和分支差异，让每条意见都有具体证据。',asset:'差异样本 · Skill 包 · 漏审测试'},
  {id:'automation',title:'定时检查链接，异常时再提醒',category:'团队自动化',output:'文档 → 异常报告',level:'进阶',status:'规划升级',desc:'先手动验证一次，再加入定时、失败处理与停止条件。',asset:'fixture · JSON Schema · 运行记录'}
];
const sample = [['D001','华东','笔记本',960],['D002','华南','鼠标',640],['D003','华东','键盘',420],['D004','华南','笔记本',360],['D005','华北','鼠标',280],['D006','华北','键盘',140]];
const prompt = '输入：sales-design-sample.csv（6 行合成设计样本）\n目标：按 region 汇总 net_sales，输出 summary.md。\n口径：net_sales 单位为人民币元；本样本不含退款、缺失或重复记录。\n约束：不修改原 CSV；不计算缺少时间字段支持的环比。\n验收：写出总额、分组汇总、使用的字段和计算方式。独立重算后再给出结论。';
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link = (path,label) => `<a class="text-link" href="https://codexhandbook.com${path}" target="_blank" rel="noopener">${label} ↗</a>`;
function action(c,label){return c.url ? `<a class="text-link" href="${c.url}" target="_blank" rel="noopener">阅读现有案例 ↗</a>` : c.id==='sales' ? `<a class="text-link" href="#case">${label||'进入设计样例'} →</a>` : `<button class="text-link" data-brief="${c.id}">${label||'查看选题说明'} →</button>`;}
function modeBar(){return `<div class="mode-row"><span>首页方向 / 切换比较布局</span><div class="segments" aria-label="首页设计方向">${[['task','A 任务优先'],['path','B 路径优先'],['reference','C 查阅优先']].map(([id,t])=>`<button data-mode="${id}" aria-pressed="${state.mode===id}">${t}</button>`).join('')}</div></div>`;}
function docPreview(){return `<div class="document" aria-label="周报设计样本预览"><div class="document-head"><span>SUMMARY.MD</span><span>合成样本 · 6 行</span></div><h3>销售汇总 · 练习报告</h3><p class="caption">同一份输入，同一套可复核口径。</p><div class="document-total">2,800 <small>元 / 销售总额</small></div>${[['华东',1380,100],['华南',1000,72.46],['华北',420,30.43]].map(([r,v,w])=>`<div class="bar-row"><span>${r}</span><div class="bar-track"><i style="width:${w}%"></i></div><span>${v.toLocaleString()}</span></div>`).join('')}<div class="document-bottom">核对依据：net_sales 求和，按 region 分组。</div></div>`;}
function tasks(){return `<div class="section-head"><div><h2>今天，先完成一件事</h2><p>每个练习都围绕一个可检查的成果。</p></div><a class="text-link" href="#library">全部选题 →</a></div><div class="task-grid">${cases.slice(0,3).map((c,i)=>`<article class="task-card"><span class="index">0${i+1} / ${c.category} <span class="badge">规划</span></span><h3>${c.title}</h3><p>${c.desc}</p><div class="meta">${c.output}</div>${action(c)}</article>`).join('')}</div>`;}
function home(){
 let hero = state.mode==='task' ? `<section class="hero"><div><div class="eyebrow">从理解，到独立完成</div><h1>从一个小任务，<br>做出一份<em>能用的成果。</em></h1><p>带着材料开始，跟着步骤执行，用检查表验收。把第一次成功，变成下一次可以复用的方法。</p><div class="actions"><a class="primary" href="#case">开始周报设计样例 →</a><a class="secondary" href="#library">浏览实战案例</a></div><p class="footnote">无需先读完整本手册。先完成任务，再回来补知识。</p></div>${docPreview()}</section>` : state.mode==='path' ? `<section class="path-hero"><div><div class="eyebrow">按照你的目标，循序渐进</div><h1>把零散的技巧，<br>连成一条学习路径。</h1><p>每一步带走一份产物，下一步用它继续。知识按需要出现，不用从头背完目录。</p><div class="actions"><a href="#paths" class="primary">选择我的学习路径 →</a><a href="#library" class="secondary">直接做一个任务</a></div></div><div class="mini-path"><div><small>01 / 研究与整理</small><h3>从材料里找到有依据的事实</h3></div><div><small>02 / 写作与编辑</small><h3>把事实写成一篇清楚的文章</h3></div><div><small>03 / 表达与交付</small><h3>把文章做成可演示的文稿</h3></div><p class="compact">创作者路径 · 待补齐的连续练习</p></div></section>` : `<section class="reference-hero"><div class="eyebrow">随用随查的工作手册</div><h1>遇到问题，<br>先找到准确的下一步。</h1><p>从任务、文件、权限或扩展入手，回到解决问题的具体步骤。</p><form class="reference-search" id="reference-search"><input class="search" name="q" aria-label="搜索原型案例" placeholder="搜索案例，例如：表格、文章、Bug"><button class="primary">搜索案例</button></form><div class="topic-list"><div><h3>开始与配置</h3>${link('/guide/getting-started/','快速上手')}${link('/guide/choose-your-client/','选择客户端')}${link('/guide/permissions-and-sandbox/','权限与沙箱')}</div><div><h3>把任务做好</h3>${link('/prompts/templates/','提示词模板')}${link('/guide/context-and-files/','上下文与文件')}${link('/guide/verification/','结果验证')}</div><div><h3>扩展与恢复</h3>${link('/skills/','Skills 与扩展')}${link('/guide/reference/troubleshooting/','故障排查')}${link('/cases/workflows/failure-recovery/','失败恢复')}</div></div></section>`;
 return modeBar()+hero+tasks()+`<div class="bottom-callout"><div><h3>第一次使用，或者想系统学一遍？</h3><p>初学者、创作者、开发者、团队，各有明确的下一步。</p></div><a class="text-link" href="#paths">选择学习路径 →</a></div>`;
}
function cardList(){const q=state.query.toLowerCase().trim();const aliases={表格:'csv',周报:'周报',代码:'代码'};const term=aliases[q]||q;const filtered=cases.filter(c=>(state.category==='全部'||c.category===state.category)&&`${c.title} ${c.desc} ${c.output} ${c.category}`.toLowerCase().includes(term));return {count:filtered.length,html:filtered.length?filtered.map(c=>`<article class="library-card"><div><span class="eyebrow">${c.category}</span> <span class="badge ${c.url?'existing':''}">${c.status}</span></div><h3>${c.title}</h3><p>${c.desc}</p><div class="meta">${c.level} <span>·</span> ${c.output}</div><div class="compact muted">${c.asset}</div><div class="card-foot"><span>${c.url?'材料已存在':'待制作完整教学包'}</span>${action(c)}</div></article>`).join(''):`<div class="empty"><h3>没有匹配的选题</h3><p>试试其他关键词，或清除分类与关键词。</p><button class="secondary" data-reset>清除筛选</button></div>`};}
function library(){const result=cardList();return `<div class="page-intro"><div class="eyebrow">实践，把知识变成自己的能力</div><h1>从一个任务开始</h1><p>先看你想交付什么，再选合适的练习。以下为设计精选样本，包含现有材料和规划选题。</p></div><div class="filter-row"><div class="segments" aria-label="案例分类">${['全部','办公分析','内容创作','软件开发','团队自动化'].map(c=>`<button data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><input id="case-search" class="search" aria-label="搜索案例" placeholder="搜索任务或产物" value="${esc(state.query)}"></div><p class="result-count" id="result-count" aria-live="polite">${result.count} 个设计条目 · 不是全站案例总数</p><div class="library-grid" id="case-list">${result.html}</div>`;}
const stepNames=['准备材料','说明任务','核对结果','失败恢复'];
function stepBody(){return [
 `<h2 tabindex="-1" id="step-title">01 / 准备一份能核对的数据</h2><p>用下面 6 行合成数据观察这套学习流程。正式案例会增加日期、退款、重复与缺失等边界条件。</p><div class="table-wrap"><table><caption>合成设计样本（金额单位：人民币元）</caption><thead><tr><th>订单</th><th>地区</th><th>产品</th><th>销售额</th></tr></thead><tbody>${sample.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><a class="primary" href="assets/sales-design-sample.csv" download="sales-design-sample.csv">下载 6 行设计样本 CSV ↓</a><div class="note">这是真实可下载的设计样本，不是完整课程包。不包含真实客户数据。</div><h3>这一步完成的标志</h3><p>你知道每一列的意思，确认金额单位，并把文件放入练习目录。</p>`,
 `<h2 tabindex="-1" id="step-title">02 / 写清目标、边界和验收</h2><p>先告诉 Codex 使用哪份数据、交付什么、怎么算完成。不需要为这个明确的小任务逐步等待确认。</p><div class="code-box"><pre id="prompt-text">${esc(prompt)}</pre><button class="quiet" data-copy>复制这段提示词</button></div><h3>为什么这里不算环比？</h3><p>样本没有日期与上期数据。遇到输入不足，应指出缺口，不能让模型补出一个看似合理的百分比。</p><h3>这一步完成的标志</h3><p>输出要求可以检查，指标口径明确，原始数据不会被覆盖。</p>`,
 `<h2 tabindex="-1" id="step-title">03 / 用独立计算核对结果</h2><p>把报告与参考值对照，不依赖 Agent 说「已经检查」。合成样本的结果如下。</p><div class="table-wrap"><table><thead><tr><th>检查项</th><th>参考结果</th><th>依据</th></tr></thead><tbody><tr><td>销售总额</td><td>2,800 元</td><td>6 行 net_sales 求和</td></tr><tr><td>华东</td><td>1,380 元</td><td>960 + 420</td></tr><tr><td>华南</td><td>1,000 元</td><td>640 + 360</td></tr><tr><td>华北</td><td>420 元</td><td>280 + 140</td></tr></tbody></table></div><h3>交付物中还应该有什么</h3><ul><li>输入文件名、使用字段与金额单位。</li><li>分组规则，以及数据没有支持的结论。</li><li>重算方式与仍需人工检查的限制。</li></ul><div class="note">原型展示的是预先计算的参考值，没有在这里运行 AI。完整案例发布前仍需实际执行与复核。</div>`,
 `<h2 tabindex="-1" id="step-title">04 / 结果不对时，先找差异</h2><h3>找不到文件</h3><p>核对项目目录和文件名。向任务提供准确路径，不要让它自行寻找整台电脑里的销售资料。</p><h3>总额与参考值不同</h3><p>先看是否漏行、重复读入或把金额当文本；只修改一个处理规则，再重新计算。</p><h3>报告里出现环比或增长结论</h3><p>本样本没有时间维度。要求删除不受输入支持的结论，并说明还需要什么数据。</p><div class="note">设计反例提示词：「先不要继续写报告。列出你实际读取的行数、使用的列与每个地区的求和明细，对照参考值定位差异。」</div><h3>下一步</h3><p>在正式课程中，这一步会连接带异常数据的练习和可复用 Skill。</p><a class="secondary" href="#paths">查看后续学习路径 →</a>`
 ][state.step];}
function detail(){return `<div class="breadcrumb"><a href="#library">实战案例</a> / 办公分析 / 设计样例</div><div class="case-header"><span class="eyebrow">CASE 01 · 规划预览</span><h1>把销售数据变成一份可核对的周报</h1><p>从读懂数据，到得到汇总结果，再亲手验证关键数字。这里展示未来案例的页面结构和学习流程。</p><div class="meta"><span>入门</span><span>规划目标 30—45 分钟，待实测</span><span>产物：Markdown + CSV</span></div></div><div class="case-layout"><nav class="steps" aria-label="案例步骤"><small>完成一个小闭环</small>${stepNames.map((s,i)=>`<button data-step="${i}" ${i===state.step?'aria-current="step"':''}>0${i+1}　${s}</button>`).join('')}</nav><article class="step-body">${stepBody()}<div class="step-footer">${state.step>0?`<button class="secondary" data-step="${state.step-1}">← 上一步</button>`:'<span></span>'}${state.step<3?`<button class="primary" data-step="${state.step+1}">下一步：${stepNames[state.step+1]} →</button>`:'<a class="text-link" href="#library">回到案例库 →</a>'}</div></article><aside class="check-panel"><h3>怎样才算完成？</h3>${['总额与分组能独立复核','报告说明字段和计算口径','原始文件保持不变'].map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}><span>${t}</span></label>`).join('')}<div id="check-count" class="check-count">已自检 ${state.checks.filter(Boolean).length} / 3 项</div><p>勾选只表示你的自检，不代表系统验证。刷新后不保留。</p></aside></div>`;}
const paths={
 beginner:{name:'初学者',desc:'先用一个小任务熟悉文件、范围和检查结果。',dependency:'前置：能打开一个练习目录。',steps:[['准备练习目录','一个可丢弃、无敏感信息的文件夹','首次开始','/guide/getting-started/create-your-first-project/'],['给出第一个明确任务','目标、范围、产物和验收说明','已有练习目录','/guide/learning-paths/beginner/03-give-clear-tasks/'],['完成一个小样例','一份可核对的数据汇总','理解输入字段','sales'],['检查并记录过程','检查表与下一次改进点','已生成产物','/guide/learning-paths/beginner/04-review-results/']]},
 creator:{name:'创作者',desc:'从整理资料开始，完成文章、演示与可复用流程。',dependency:'前置：完成第一次任务，知道如何查看和保存文件。',steps:[['整理资料，建立事实表','来源清单 + 待确认问题','起点：三份示例资料','article'],['完成一篇带来源的文章','初稿 + 修改 diff + 终稿','使用上一步事实表','article'],['把文章做成 8 页演示稿','大纲 + 可编辑 PPTX + 预览','依赖已核对的终稿','slides'],['将成熟过程封装为 Skill','SKILL.md + 输入样本 + 触发测试','先重复完成一次流程','/skills/examples/writing-skill/']]},
 developer:{name:'开发者',desc:'用现有代码练习，把探索、修改、测试和审查连起来。',dependency:'前置：能运行项目测试，了解基本 Git 操作。',steps:[['理解一个代码库','模块说明 + 修改边界','已有练习仓库','/cases/understand-a-codebase/'],['修复一个可复现的 Bug','最小 diff + 红绿测试','使用现有购物车练习','bug'],['审查变更并补充证据','有定位信息的审查报告','已有修改和测试结果','review'],['写交接记录','目标、完成项、剩余问题','已经核对产物','/guide/agent-work/handoff-and-resume/']]},
 team:{name:'团队',desc:'从小范围试点开始，用共同的交付与检查标准建立习惯。',dependency:'前置：明确维护者、复核者和可用于试点的任务。',steps:[['挑选试点任务','范围说明 + 风险边界','不从生产写操作开始','/guide/team-enterprise/'],['约定规则与权限','AGENTS.md + 验收清单','由维护者审核规则','/guide/customization/rules/team-rules/'],['试跑一次只读自动化','日志 + 结构化建议 + 人工反馈','流程已手动验证','automation'],['根据证据决定是否推广','质量、返工和成本记录','至少复盘一个完整任务','/guide/quality/definition-of-done/']]}
};
function pathAction(id){if(id.startsWith('/'))return link(id,'阅读现有章节');if(id==='sales')return '<a class="text-link" href="#case">进入设计样例 →</a>';return action(cases.find(c=>c.id===id),'查看内容规划');}
function learning(){const p=paths[state.role];return `<div class="page-intro"><div class="eyebrow">每一步，都带走一份产物</div><h1>找到适合你的学习路径</h1><p>路径负责安排练习，手册负责随时回查。以下展示下一版的里程碑设计。</p></div><div class="segments role-tabs" aria-label="学习角色">${Object.entries(paths).map(([id,p])=>`<button data-role="${id}" aria-pressed="${state.role===id}">${p.name}</button>`).join('')}</div><div class="path-summary"><div><h2>${p.name}路径</h2><p>${p.desc}</p></div><div class="note">${p.dependency}<br>新增节点为规划；已存在章节会明确跳转现站。</div></div><ol class="path-list">${p.steps.map(([title,out,dep,id],i)=>`<li class="path-item"><span class="step-num">0${i+1}</span><div><h3>${title}</h3><p>带走：${out}</p><div class="dependency">${dep}</div></div>${pathAction(id)}</li>`).join('')}</ol>`;}
const phases=[
 {name:'建立可信的起点',subtitle:'先修正误导和阅读障碍，再用一个完整练习兑现实战承诺。',gate:'周报材料、计算依据和实际运行记录齐全；首页能直接进入练习；价格估算不再冒充实际报价。',items:[['T01','报价与估算分离','没有核验来源的套餐不进入实际价格排行','P1'],['T02','区分内容状态与验证方式','明确来源核验、编辑审阅和实际运行','P1'],['T03','标题、封面与上下篇整理','一个主标题，下一步与学习路径一致','P2'],['T04','销售周报完整练习','CSV、字典、参考产物、独立计算与失败恢复','P1'],['T05','任务优先首页与案例入口','依赖 T03、T04，不能先上线空案例入口','P1']]},
 {name:'连成完整的学习路径',subtitle:'用文章与演示稿接续创作流程，让角色路径有实际交付。',gate:'三篇首批案例拥有完整材料和验收；两条个人路径可连续学习；产品边界有精确来源。',items:[['T06','带来源文章练习','三份资料、事实表、初稿、终稿与复盘','P1'],['T07','可编辑演示稿练习','依赖 T06；8 页 PPTX 与视觉验证','P1'],['T08','创作者路径','串联 T04、T06、T07 的实际产物','P1'],['T09','开发者路径','复用现有 Bug 练习，补审查与交接','P1'],['T10','指令层级与 SDK 边界核验','消除泛化描述，提供具体来源和环境','P1'],['T11','任务分级与确认时机','简单任务连续完成，复杂任务设置检查点','P2']]},
 {name:'让方法可以复用',subtitle:'从骨架走向示例包，从成功流程走向可重现的失败恢复。',gate:'四个 Skill 包可安装、有输入输出与触发反例；自动化有手动验证、异常与停止条件。',items:[['T12','PR 审查 Skill 包','staged / unstaged / 基线三种范围','P1'],['T13','写作 Skill 包','复用文章案例与事实核对表','P2'],['T14','研究 Skill 包','处理证据冲突、来源失效与未知问题','P2'],['T15','自动化 Skill 包','依赖 T18；运行、记录与停止','P2'],['T16','三组提示词对照实验','固定输入，解释输出差异与限制','P2'],['T17','五类失败恢复实例','真实或明确标注的设计反例与日志','P1'],['T18','团队自动化案例升级','合法 schema、fixtures 与干运行','P1']]},
 {name:'建立持续维护机制',subtitle:'用评估和变化记录维护内容，把个人经验推进到团队试点。',gate:'每项事实与实跑状态可追溯；团队试点有清晰责任与退出条件；不承诺无数据支持的成功率。',items:[['T19','用量与模型选择实践','区分额度、API 费用、时间与返工','P2'],['T20','工作流评估方法','触发、拒答、格式、质量分项记录','P2'],['T21','两周团队试点','角色、抽检、回退和推广决定','P2'],['T22','内容更新与就地纠错','更新关联页面、影响与验证记录','P2'],['T23','路线图口径与实践链接','区分历史事件、厂商发布和作者判断','P2'],['T24','宠物、主题兼容与恢复','声明已测试环境，记录恢复操作','P2']]}
];
function roadmap(){const p=phases[state.phase];return `<div class="page-intro"><div class="eyebrow">维护者视图 · 编辑排期</div><h1>下一章，按这个顺序建设</h1><p>四个批次，24 项明确交付。以验收门槛推进，不用空页面增加内容数量。</p></div><div class="segments" aria-label="实施批次">${phases.map((p,i)=>`<button data-phase="${i}" aria-pressed="${i===state.phase}">第 ${i+1} 批</button>`).join('')}</div><div class="phase-title"><h2>${p.name}</h2><p>${p.subtitle}</p></div>${p.items.map(([id,t,d,priority])=>`<article class="work-item"><code>${id}</code><div><h3>${t}</h3><p>${d}</p></div><span class="badge">${priority}</span></article>`).join('')}<div class="phase-gate"><strong>这一批怎样算完成</strong><p>${p.gate}</p></div><div class="bottom-callout"><p>工作量、依赖和负责角色见完整规划。批次不是承诺发布日期。</p><a class="text-link" href="content-plan.md">阅读完整规划 ↗</a></div>`;}
function route(){return location.hash.slice(1)||'home';}
function render(focus=false){const r=route();const views={home,library,case:detail,paths:learning,roadmap};main.innerHTML=(views[r]||home)();document.querySelectorAll('[data-route]').forEach(a=>{if(a.dataset.route===r)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
let toastTimer;
function toast(text){const box=document.querySelector('#toast');box.textContent=text;box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),3500);}
function showBrief(id){const c=cases.find(x=>x.id===id);if(!c)return;document.querySelector('#brief-body').innerHTML=`<span class="eyebrow">待制作内容 · 选题说明</span><h2 id="brief-title">${c.title}</h2><p>${c.desc}</p><div class="note">计划交付：${c.asset}</div><p>这是下一阶段内容规格，完整教学包尚未制作。发布前需要实际运行、参考产物和失败恢复记录。</p><a class="text-link" href="editorial-briefs.md">阅读首批作者 brief ↗</a>`;document.querySelector('#brief-dialog').showModal();}
document.addEventListener('click',async e=>{
 if(e.target.closest('.skip')){e.preventDefault();main.focus();return;}
 const b=e.target.closest('button');if(!b)return;
 if(b.id==='theme-toggle'){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';b.textContent=dark?'浅色':'深色';b.setAttribute('aria-label',dark?'切换为浅色外观':'切换为深色外观');return;}
 if(b.dataset.mode){state.mode=b.dataset.mode;render();main.querySelector(`[data-mode="${state.mode}"]`).focus();}
 if(b.dataset.category){state.category=b.dataset.category;render();main.querySelector(`[data-category="${state.category}"]`).focus();}
 if(b.hasAttribute('data-reset')){state.category='全部';state.query='';render();document.querySelector('#case-search').focus();}
 if(b.dataset.step!==undefined){state.step=Number(b.dataset.step);render();document.querySelector('#step-title').focus({preventScroll:true});}
 if(b.dataset.role){state.role=b.dataset.role;render();main.querySelector(`[data-role="${state.role}"]`).focus();}
 if(b.dataset.phase!==undefined){state.phase=Number(b.dataset.phase);render();main.querySelector(`[data-phase="${state.phase}"]`).focus();}
 if(b.dataset.brief)showBrief(b.dataset.brief);
 if(b.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(prompt);toast('提示词已复制');}catch{const range=document.createRange();range.selectNodeContents(document.querySelector('#prompt-text'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('浏览器未允许自动复制，已选中文本，请手动复制');}}
});
document.addEventListener('input',e=>{if(e.target.id==='case-search'){state.query=e.target.value;const result=cardList();document.querySelector('#case-list').innerHTML=result.html;document.querySelector('#result-count').textContent=`${result.count} 个设计条目 · 不是全站案例总数`;}});
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){state.checks[Number(e.target.dataset.check)]=e.target.checked;document.querySelector('#check-count').textContent=`已自检 ${state.checks.filter(Boolean).length} / 3 项`;}});
document.addEventListener('submit',e=>{if(e.target.id==='reference-search'){e.preventDefault();state.query=new FormData(e.target).get('q');state.category='全部';location.hash='library';}});
window.addEventListener('hashchange',()=>render(true));render();
